# ==============================================================================# 020_METRICS_ENGINE.py# ==============================================================================import sqlite3import jsonfrom pathlib import Pathfrom datetime import datetimeROOT = Path(__file__).resolve().parentDB = ROOT / "MISSION_CONTROL" / "database" / "mission_control.db"conn = sqlite3.connect(DB, timeout=30)conn.row_factory = sqlite3.Rowcur = conn.cursor()

cur.execute("PRAGMA journal_mode=WAL")
cur.execute("PRAGMA synchronous=NORMAL")
cur.execute("PRAGMA busy_timeout=30000")cur.execute("""CREATE TABLE IF NOT EXISTS metrics(    id INTEGER PRIMARY KEY AUTOINCREMENT,    timestamp TEXT,    metric TEXT,    value REAL,    unit TEXT)""")conn.commit()def total(table):    try:        cur.execute(f"SELECT COUNT(*) total FROM {table}")        return cur.fetchone()["total"]    except:        return 0dados = {    "missions": total("missions"),    "events": total("events"),    "logs": total("system_logs"),    "maestro": total("maestro_history"),    "api": total("api_requests"),    "observability": total("observability")}for k, v in dados.items():    cur.execute("""        INSERT INTO metrics(            timestamp,            metric,            value,            unit        )        VALUES(?,?,?,?)    """, (        datetime.now().isoformat(),        k,        v,        "count"    ))conn.commit()cur.execute("""SELECT metric,valueFROM metricsORDER BY id DESCLIMIT 20""")print("="*80)print("METRICS ENGINE")print("="*80)for r in cur.fetchall():    print(f"{r['metric']:<20} {int(r['value'])}")print("="*80)conn.close()

